       AND (SELECT count(*) FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)) = 1;
  FOR v_row IN
    SELECT (pg_catalog.jsonb_populate_record(NULL::"hd"."tickets", pg_catalog.to_jsonb(n.*))).* FROM new_rows n
    WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text AND o."status" IS NOT DISTINCT FROM n."status")
      AND NOT (authz__.v_one AND NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)
               AND EXISTS (SELECT 1 FROM old_rows o WHERE o."status" IS NOT DISTINCT FROM n."status"
                           AND NOT EXISTS (SELECT 1 FROM new_rows m WHERE m."id"::text = o."id"::text)))
  LOOP
    IF v_virtual IS NOT NULL THEN
      EXECUTE 'SELECT (pg_catalog.jsonb_populate_record($1, pg_catalog.jsonb_build_object(' || v_virtual
        || '))).* FROM (SELECT ($1).*) AS r' INTO v_row USING v_row;
    END IF;
    IF NOT (authz_gen."hd.tickets:column status after:items"(v_row, current_user))[1] THEN
      BEGIN
        v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."hd.tickets:column status after:why"(v_row) l);
      EXCEPTION WHEN OTHERS THEN
        v_lines := 'no explanation: ' || SQLERRM;
      END;
      RAISE EXCEPTION 'changing status of hd.tickets % needs: work or {status in (''open'', ''solved'')}', v_row."id" USING ERRCODE = 'insufficient_privilege', DETAIL = v_lines,
        SCHEMA = 'hd', TABLE = 'tickets', CONSTRAINT = 'authz_update', HINT = 'rowstile help AZ709';
    END IF;
  END LOOP;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."hd.tickets:column team_id, assignee_id:why"(p_row "hd"."tickets") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE v boolean[] := authz_gen."hd.tickets:column team_id, assignee_id:items"(p_row, current_user); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update team_id, assignee_id : work  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule hd.tickets update team_id, assignee_id'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT CASE WHEN coalesce(pg_catalog.current_setting('authz.acting_user', true), '') <> ''
    THEN '  no   the session views as someone else: it may not update on hd.tickets'
    ELSE '  no   the sign-in''s scopes do not allow update on hd.tickets' END; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'work';
  IF NOT v[4] THEN
    RETURN QUERY SELECT '    ' || l FROM authz.explain('ticket', ((p_row)."id"::text), 'work') l LIMIT 20;
  END IF;
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."hd.tickets:column id, workspace_id, requester_id:why"(p_row "hd"."tickets") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE v boolean[] := authz_gen."hd.tickets:column id, workspace_id, requester_id:items"(p_row, current_user); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update id, workspace_id, requester_id : nobody  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule hd.tickets update id, workspace_id, requester_id'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT CASE WHEN coalesce(pg_catalog.current_setting('authz.acting_user', true), '') <> ''
    THEN '  no   the session views as someone else: it may not update on hd.tickets'
    ELSE '  no   the sign-in''s scopes do not allow update on hd.tickets' END; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'nobody';
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."hd.tickets:column created_at:why"(p_row "hd"."tickets") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE v boolean[] := authz_gen."hd.tickets:column created_at:items"(p_row, current_user); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update created_at : nobody  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule hd.tickets update created_at'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT CASE WHEN coalesce(pg_catalog.current_setting('authz.acting_user', true), '') <> ''
    THEN '  no   the session views as someone else: it may not update on hd.tickets'
    ELSE '  no   the sign-in''s scopes do not allow update on hd.tickets' END; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'nobody';
END $f$;

-- What the app role evaluates itself (its rules, the views they read, the rules' own functions, the masked views)
-- calls nothing of the app's that may read data: a call the condition's text doesn't show isn't run as the owner
DO $ac$
DECLARE r record;
BEGIN
  FOR r IN
    WITH RECURSIVE read(classid, objid, what) AS (
      SELECT x.classid, x.objid, x.what FROM (
        SELECT 'pg_policy'::regclass::oid AS classid, p.oid AS objid,
               format('the %s rule of %s', substr(p.polname::text, 7), p.polrelid::regclass) AS what
        FROM pg_policy p JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
         AND d.description IN ('rowstile')
        UNION ALL
        SELECT 'pg_proc'::regclass::oid, f.oid, 'the rules of ' || split_part(f.proname::text, ':', 1)
        FROM pg_proc f WHERE f.pronamespace = 'authz_gen'::regnamespace
        UNION ALL
        SELECT 'pg_rewrite'::regclass::oid, w.oid, 'the masked view ' || c.oid::regclass
        FROM pg_class c JOIN pg_description d ON d.objoid = c.oid AND d.classoid = 'pg_class'::regclass
         AND d.description IN ('rowstile masked view')
        JOIN pg_rewrite w ON w.ev_class = c.oid) x
      UNION
      -- (the views they read, and those these read: a view runs what it calls as whoever reads it)
      SELECT 'pg_rewrite'::regclass::oid, w.oid, rd.what
      FROM read rd JOIN pg_depend dep ON dep.classid = rd.classid AND dep.objid = rd.objid
       AND dep.refclassid = 'pg_class'::regclass
      JOIN pg_class v ON v.oid = dep.refobjid AND v.relkind = 'v' AND v.relnamespace = 'authz_int'::regnamespace
      JOIN pg_rewrite w ON w.ev_class = v.oid)
    SELECT rd.what, fn.oid::regprocedure::text AS fn
    FROM read rd JOIN pg_depend dep ON dep.classid = rd.classid AND dep.objid = rd.objid
    JOIN pg_proc fn ON fn.oid = CASE dep.refclassid
        WHEN 'pg_proc'::regclass THEN dep.refobjid
        WHEN 'pg_operator'::regclass THEN (SELECT o.oprcode FROM pg_operator o WHERE o.oid = dep.refobjid) END
    WHERE fn.pronamespace NOT IN (SELECT n.oid FROM pg_namespace n
                                  WHERE n.nspname IN ('pg_catalog', 'authz', 'authz_gen', 'authz_int'))
      AND fn.provolatile <> 'i'
      AND fn.prolang NOT IN (SELECT l.oid FROM pg_language l WHERE l.lanname IN ('internal', 'c'))
    ORDER BY 1, 2 LIMIT 1
  LOOP
    RAISE EXCEPTION '%: a condition calls %, and nothing in its text shows the call (a function of the row read as a column, a cast, an operator written OPERATOR(...)), so the app role would run it with its own rights, not the policy''s [AZ628]', r.what, r.fn
      USING HINT = 'call it by its name, with parentheses, on the row''s columns, as {app.blocked_doc(this.id)}: rowstile then runs it with the policy''s rights. A function that reads nothing may be marked IMMUTABLE instead';
  END LOOP;
END $ac$;

-- A permission on an object, whether the user may select its row or not: what the functions that act on the
-- object ask (sharing, roles, keys, view_as, break_glass, requests), where authz.can's answer is for rows they may see
CREATE OR REPLACE FUNCTION authz_int.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE v_text text; v_uuid uuid;
BEGIN
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'workspace' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")));
        WHEN 'manage_roles' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")));
        WHEN 'work_all' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
    OR (coalesce((open_queue), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")))));
        WHEN 'work' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id")));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'impersonate' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))));
        WHEN 'see_notes' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))));
        WHEN 'org_tickets' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."customer_org__see_tickets" v WHERE v.id = o."customer_org_id")
    AND coalesce((active), false))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = authz__.v_uuid AND (((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (coalesce((kind = 'agent'), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'integration' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage_keys' THEN RETURN EXISTS (SELECT 1 FROM "hd"."integrations" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."integrations" o WHERE o."id" = authz__.v_uuid AND (((coalesce(o."id" = (SELECT authz_int."integration__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'customer_org' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'see_tickets' THEN RETURN EXISTS (SELECT 1 FROM "hd"."customer_orgs" o WHERE o."id" = authz__.v_uuid AND ((coalesce((shared_tickets), false)
    AND EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id"))));
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."customer_orgs" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."customer_orgs" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'oversee' THEN RETURN EXISTS (SELECT 1 FROM "hd"."teams" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."team__lead" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."parent_id"))));
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."teams" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."team__lead" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."parent_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."teams" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'membership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."membership__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."membership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'leadership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."leadership__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."leadership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'support_grant' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."support_grant__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."support_grant__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'ticket' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'work' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        WHEN 'reply' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."user__org_tickets" v WHERE v.id = o."requester_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")));
        WHEN 'share' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")));
        WHEN 'break_glass' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__support" v WHERE v.id = o."workspace_id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'comment' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."comments" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."ticket__work" v WHERE v.id = o."ticket_id")
    OR (coalesce((not internal), false)
    AND EXISTS (SELECT 1 FROM authz_int."ticket__view" v WHERE v.id = o."ticket_id")))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist, and on a table with a select rule only rows the user may select: a row they can't see
-- reads as a missing one; plans are cached per session)
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE v_allowed boolean; v_text text; v_uuid uuid;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log), naming who acted as the
    -- audit trail does ('42', 'service:7'; none: nobody signed in). A check answers true or false; one that raises
    -- (a type or a permission the policy doesn't have) is not logged
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(authz_int.actor())::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, v_allowed::text;
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'workspace' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id"))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")));
        WHEN 'manage_roles' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id"))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")));
        WHEN 'work_all' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
    OR (coalesce((open_queue), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id"))))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")));
        WHEN 'work' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id"))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'impersonate' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false)))
    AND ((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (coalesce((kind = 'agent'), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id"))));
        WHEN 'see_notes' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false)))
    AND ((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (coalesce((kind = 'agent'), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id"))));
        WHEN 'org_tickets' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."customer_org__see_tickets" v WHERE v.id = o."customer_org_id")
    AND coalesce((active), false)))
    AND ((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (coalesce((kind = 'agent'), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."users" o WHERE o."id" = authz__.v_uuid AND (((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (coalesce((kind = 'agent'), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'integration' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage_keys' THEN RETURN EXISTS (SELECT 1 FROM "hd"."integrations" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false)))
    AND ((coalesce(o."id" = (SELECT authz_int."integration__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."integrations" o WHERE o."id" = authz__.v_uuid AND (((coalesce(o."id" = (SELECT authz_int."integration__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id"))
    AND coalesce((active), false))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'customer_org' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'see_tickets' THEN RETURN EXISTS (SELECT 1 FROM "hd"."customer_orgs" o WHERE o."id" = authz__.v_uuid AND ((coalesce((shared_tickets), false)
    AND EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id")))
    AND ((EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id"))));
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."customer_orgs" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id"))
    AND ((EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."customer_orgs" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'oversee' THEN RETURN EXISTS (SELECT 1 FROM "hd"."teams" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."team__lead" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."parent_id")))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")));
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."teams" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."team__lead" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."parent_id")))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."teams" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'membership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."membership__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."membership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'leadership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."leadership__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."leadership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'support_grant' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."support_grant__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."support_grant__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'ticket' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'work' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        WHEN 'reply' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."user__org_tickets" v WHERE v.id = o."requester_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id"))
    AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."user__org_tickets" v WHERE v.id = o."requester_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        WHEN 'share' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = o."workspace_id"))
    AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."user__org_tickets" v WHERE v.id = o."requester_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        WHEN 'break_glass' THEN RETURN EXISTS (SELECT 1 FROM "hd"."tickets" o WHERE o."id" = authz__.v_uuid AND (EXISTS (SELECT 1 FROM authz_int."workspace__support" v WHERE v.id = o."workspace_id"))
    AND ((EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = o."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = o."id")
    OR ((coalesce(o."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = o."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."user__org_tickets" v WHERE v.id = o."requester_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."workspace_id")
    AND (coalesce(o."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = o."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = o."id")
    OR authz_int."team__oversee__has"(o."team_id"))))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'comment' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "hd"."comments" o WHERE o."id" = authz__.v_uuid AND ((EXISTS (SELECT 1 FROM authz_int."ticket__work" v WHERE v.id = o."ticket_id")
    OR (coalesce((not internal), false)
    AND EXISTS (SELECT 1 FROM authz_int."ticket__view" v WHERE v.id = o."ticket_id")))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Everything the user holds a permission on: SELECT * FROM authz.list('folder', 'edit')
-- In pages, in key order: authz.list('file', 'view', NULL, 1000), then the last id seen as p_after
CREATE OR REPLACE FUNCTION authz.list(p_type text, p_perm text, p_after text DEFAULT NULL, p_limit int DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
  -- a page cursor or size from a request: the caller's mistake, said plainly (the queries below would cast it)
  IF p_limit < 0 THEN
    RAISE EXCEPTION 'the page size must not be negative (got %)', p_limit
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF p_after IS NOT NULL AND NOT coalesce(pg_catalog.pg_input_is_valid(p_after,
                                            (SELECT keytype FROM authz_int.types WHERE name = p_type)), true) THEN
    RAISE EXCEPTION 'the page cursor % is not a % id', quote_literal(left(p_after, 40)), p_type
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'workspace.manage' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE ((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id"))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE ((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id"))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT $4;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > $3::uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id"))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT $4;
      END IF;
    WHEN 'workspace.manage_roles' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE ((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id"))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE ((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id"))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT $4;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > $3::uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id"))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT $4;
      END IF;
    WHEN 'workspace.work_all' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE (((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
    OR (coalesce((open_queue), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id"))))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE (((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
    OR (coalesce((open_queue), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id"))))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT $4;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > $3::uuid AND (((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."id")
    OR (coalesce((open_queue), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id"))))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT $4;
      END IF;
    WHEN 'workspace.work' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE ((EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id"))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE ((EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id"))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT $4;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > $3::uuid AND ((EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = o."id"))
    AND (EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")))
        ORDER BY o."id" LIMIT $4;
      END IF;
    WHEN 'workspace.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT $4;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "hd"."workspaces" o
        WHERE o."id" > $3::uuid AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."id")
        ORDER BY o."id" LIMIT $4;
      END IF;
    WHEN 'user.impersonate' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
        WHERE (((EXISTS (SELECT 1 FROM authz_int."workspace__admin" v WHERE v.id = o."workspace_id")
    AND coalesce((active), false)))
    AND ((coalesce(o."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = o."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = o."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR (coalesce((kind = 'agent'), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = o."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = o."workspace_id"))));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "hd"."users" o
