    v_ok := ($1) IN (SELECT r."id" AS id FROM "hd"."workspaces" r WHERE coalesce((open_queue), false));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{open_queue}';
  END;
END $f$;

