    v_ok := ($1) IN (SELECT id FROM authz_int."ticket__responder");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'responder';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."ticket__responder__why"($1, p_depth + 1, p_seen, p_asker); END IF;
  END;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."ticket__reply__why"(p_id uuid, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."ticket__reply");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'ticket.reply = work or ((requester or cc) and workspace.member)';
  BEGIN
    v_ok := ($1) IN (SELECT id FROM authz_int."ticket__work");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'work';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."ticket__work__why"($1, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := ($1) IN (SELECT r."id" AS id FROM "hd"."tickets" r
  WHERE r."id" IN ((SELECT id FROM authz_int."ticket__requester")
  UNION ALL
  (SELECT id FROM authz_int."ticket__cc"))
    AND r."id" IN (SELECT id FROM authz_int."ticket__workspace__member"));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '((requester or cc) and workspace.member)';
    v_ok := ($1) IN ((SELECT id FROM authz_int."ticket__requester")
  UNION ALL
  (SELECT id FROM authz_int."ticket__cc"));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(requester or cc)';
    v_ok := ($1) IN (SELECT id FROM authz_int."ticket__workspace__member");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'workspace.member';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."workspace_id" AS id FROM "hd"."tickets" r WHERE r."id" = $1 AND r."workspace_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'workspace', v_t.id, false) THEN
        RETURN NEXT pad || '  ' || '       ' || 'workspace is a workspace you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'workspace is workspace '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has member' ELSE ', without member' END;
      IF NOT ('workspace:member:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND v_holds) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        RETURN QUERY SELECT * FROM authz_int."workspace__member__why"(v_t.id::uuid, p_depth + 2 + 1, p_seen || ('workspace:member:' || v_t.id), p_asker);
      END IF;
    END LOOP;
  END;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."ticket__view__why"(p_id uuid, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."ticket__view");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'ticket.view = reply or workspace.agent or (requester.org_tickets and workspace.member) or workspace.connected';
  BEGIN
    v_ok := ($1) IN (SELECT id FROM authz_int."ticket__reply");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'reply';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."ticket__reply__why"($1, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := ($1) IN (SELECT id FROM authz_int."ticket__workspace__agent");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'workspace.agent';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."workspace_id" AS id FROM "hd"."tickets" r WHERE r."id" = $1 AND r."workspace_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'workspace', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'workspace is a workspace you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'workspace is workspace '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has agent' ELSE ', without agent' END;
      IF NOT ('workspace:agent:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."workspace__agent__why"(v_t.id::uuid, p_depth + 1 + 1, p_seen || ('workspace:agent:' || v_t.id), p_asker);
      END IF;
    END LOOP;
    v_ok := ($1) IN (SELECT r."id" AS id FROM "hd"."tickets" r
  WHERE r."id" IN (SELECT id FROM authz_int."ticket__requester__org_tickets")
    AND r."id" IN (SELECT id FROM authz_int."ticket__workspace__member"));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(requester.org_tickets and workspace.member)';
    v_ok := ($1) IN (SELECT id FROM authz_int."ticket__requester__org_tickets");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'requester.org_tickets';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."user__org_tickets" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."requester_id" AS id FROM "hd"."tickets" r WHERE r."id" = $1 AND r."requester_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'user', v_t.id, false) THEN
        RETURN NEXT pad || '  ' || '       ' || 'requester is an user you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'requester is user '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has org_tickets' ELSE ', without org_tickets' END;
      IF NOT ('user:org_tickets:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND v_holds) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        RETURN QUERY SELECT * FROM authz_int."user__org_tickets__why"(v_t.id::uuid, p_depth + 2 + 1, p_seen || ('user:org_tickets:' || v_t.id), p_asker);
      END IF;
    END LOOP;
    v_ok := ($1) IN (SELECT id FROM authz_int."ticket__workspace__member");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'workspace.member';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."workspace_id" AS id FROM "hd"."tickets" r WHERE r."id" = $1 AND r."workspace_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'workspace', v_t.id, false) THEN
        RETURN NEXT pad || '  ' || '       ' || 'workspace is a workspace you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'workspace is workspace '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has member' ELSE ', without member' END;
      IF NOT ('workspace:member:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND v_holds) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        RETURN QUERY SELECT * FROM authz_int."workspace__member__why"(v_t.id::uuid, p_depth + 2 + 1, p_seen || ('workspace:member:' || v_t.id), p_asker);
      END IF;
    END LOOP;
    v_ok := ($1) IN (SELECT id FROM authz_int."ticket__workspace__connected");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'workspace.connected';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."workspace_id" AS id FROM "hd"."tickets" r WHERE r."id" = $1 AND r."workspace_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'workspace', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'workspace is a workspace you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'workspace is workspace '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has connected' ELSE ', without connected' END;
      IF NOT ('workspace:connected:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."workspace__connected__why"(v_t.id::uuid, p_depth + 1 + 1, p_seen || ('workspace:connected:' || v_t.id), p_asker);
      END IF;
    END LOOP;
  END;
END $f$;

