CREATE OR REPLACE FUNCTION authz_int."comment__view__why"(p_id uuid, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."comment__view");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'comment.view = ticket.work or (ticket.view and {not internal})';
  BEGIN
    v_ok := ($1) IN (SELECT id FROM authz_int."comment__ticket__work");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'ticket.work';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."ticket__work" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."ticket_id" AS id FROM "hd"."comments" r WHERE r."id" = $1 AND r."ticket_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'ticket', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'ticket is a ticket you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'ticket is ticket '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has work' ELSE ', without work' END;
      IF NOT ('ticket:work:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."ticket__work__why"(v_t.id::uuid, p_depth + 1 + 1, p_seen || ('ticket:work:' || v_t.id), p_asker);
      END IF;
    END LOOP;
    v_ok := ($1) IN (SELECT r."id" AS id FROM "hd"."comments" r
  WHERE r."id" IN (SELECT id FROM authz_int."comment__ticket__view")
    AND coalesce((not internal), false));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(ticket.view and {not internal})';
    v_ok := ($1) IN (SELECT id FROM authz_int."comment__ticket__view");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'ticket.view';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."ticket__view" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."ticket_id" AS id FROM "hd"."comments" r WHERE r."id" = $1 AND r."ticket_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'ticket', v_t.id, false) THEN
        RETURN NEXT pad || '  ' || '       ' || 'ticket is a ticket you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'ticket is ticket '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has view' ELSE ', without view' END;
      IF NOT ('ticket:view:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND v_holds) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        RETURN QUERY SELECT * FROM authz_int."ticket__view__why"(v_t.id::uuid, p_depth + 2 + 1, p_seen || ('ticket:view:' || v_t.id), p_asker);
      END IF;
    END LOOP;
    v_ok := ($1) IN (SELECT r."id" AS id FROM "hd"."comments" r WHERE coalesce((not internal), false));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{not internal}';
  END;
END $f$;

-- May the signed-in user see this object (select it)? A hidden object reads as a missing one
CREATE OR REPLACE FUNCTION authz_int.visible(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
  IF NOT coalesce(pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)), false) THEN
    RETURN false;
  END IF;
  CASE p_type
    WHEN 'workspace' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."workspaces" "workspaces" WHERE "workspaces"."id" = $2::uuid
        AND (SELECT authz_int.scope_cmd('hd.workspaces', 'select')) AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "workspaces"."id"));
    WHEN 'user' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."users" "users" WHERE "users"."id" = $2::uuid
        AND (SELECT authz_int.scope_cmd('hd.users', 'select')) AND ((coalesce("users"."id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "users"."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = "users"."customer_org_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "users"."workspace_id"))
    OR (coalesce((kind = 'agent'), false)
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "users"."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = "users"."workspace_id"))
    AND coalesce((active), false)));
    WHEN 'integration' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."integrations" "integrations" WHERE "integrations"."id" = $2::uuid
        AND (SELECT authz_int.scope_cmd('hd.integrations', 'select')) AND ((coalesce("integrations"."id" = (SELECT authz_int."integration__me"()), false)
    OR EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = "integrations"."workspace_id"))
    AND coalesce((active), false)));
    WHEN 'customer_org' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."customer_orgs" "customer_orgs" WHERE "customer_orgs"."id" = $2::uuid
        AND (SELECT authz_int.scope_cmd('hd.customer_orgs', 'select')) AND (EXISTS (SELECT 1 FROM authz_int."customer_org__member" v WHERE v.id = "customer_orgs"."id")
    OR EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "customer_orgs"."workspace_id")));
    WHEN 'team' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."teams" "teams" WHERE "teams"."id" = $2::uuid
        AND (SELECT authz_int.scope_cmd('hd.teams', 'select')) AND EXISTS (SELECT 1 FROM authz_int."workspace__work" v WHERE v.id = "teams"."workspace_id"));
    WHEN 'membership' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."team_members" "team_members" WHERE ("team_members"."team_id", "team_members"."user_id") = ((($2)::authz_gen."membership__key")."team_id", (($2)::authz_gen."membership__key")."user_id")
        AND (SELECT authz_int.scope_cmd('hd.team_members', 'select')) AND EXISTS (SELECT 1 FROM authz_int."team__view" v WHERE v.id = "team_members"."team_id"));
    WHEN 'leadership' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."team_leads" "team_leads" WHERE ("team_leads"."team_id", "team_leads"."user_id") = ((($2)::authz_gen."leadership__key")."team_id", (($2)::authz_gen."leadership__key")."user_id")
        AND (SELECT authz_int.scope_cmd('hd.team_leads', 'select')) AND EXISTS (SELECT 1 FROM authz_int."team__view" v WHERE v.id = "team_leads"."team_id"));
    WHEN 'support_grant' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."support_access" "support_access" WHERE ("support_access"."workspace_id", "support_access"."staff_id") = ((($2)::authz_gen."support_grant__key")."workspace_id", (($2)::authz_gen."support_grant__key")."staff_id")
        AND (SELECT authz_int.scope_cmd('hd.support_access', 'select')) AND (EXISTS (SELECT 1 FROM authz_int."workspace__manage" v WHERE v.id = "support_access"."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."user__self" v WHERE v.id = "support_access"."staff_id")));
    WHEN 'ticket' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."tickets" "tickets" WHERE "tickets"."id" = $2::uuid
        AND (SELECT authz_int.scope_cmd('hd.tickets', 'select')) AND (EXISTS (SELECT 1 FROM authz_int."workspace__work_all" v WHERE v.id = "tickets"."workspace_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__responder" v WHERE v.id = "tickets"."id")
    OR ((coalesce("tickets"."requester_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."ticket__cc" v WHERE v.id = "tickets"."id"))
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "tickets"."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = "tickets"."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."user__org_tickets" v WHERE v.id = "tickets"."requester_id")
    AND EXISTS (SELECT 1 FROM authz_int."workspace__member" v WHERE v.id = "tickets"."workspace_id"))
    OR EXISTS (SELECT 1 FROM authz_int."workspace__connected" v WHERE v.id = "tickets"."workspace_id")
    OR (EXISTS (SELECT 1 FROM authz_int."workspace__agent" v WHERE v.id = "tickets"."workspace_id")
    AND (coalesce("tickets"."assignee_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = "tickets"."team_id")
    OR EXISTS (SELECT 1 FROM authz_int."ticket__roles:work" v WHERE v.id = "tickets"."id")
    OR authz_int."team__oversee__has"("tickets"."team_id")))));
    WHEN 'comment' THEN
      RETURN EXISTS (SELECT 1 FROM "hd"."comments" "comments" WHERE "comments"."id" = $2::uuid
        AND (SELECT authz_int.scope_cmd('hd.comments', 'select')) AND (EXISTS (SELECT 1 FROM authz_int."ticket__work" v WHERE v.id = "comments"."ticket_id")
    OR (coalesce((not internal), false)
    AND EXISTS (SELECT 1 FROM authz_int."ticket__view" v WHERE v.id = "comments"."ticket_id"))));
    ELSE RETURN false;
  END CASE;
END $f$;

-- Everyone who holds a permission on an object: SELECT * FROM authz.who('folder', 3, 'view')
-- Candidates come from the data (a superset); each is checked as that user (the permission itself, authz_int.can).
CREATE OR REPLACE FUNCTION authz.who(p_type text, p_id text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_c text;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_text text; v_uuid uuid;
BEGIN
  IF NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm) THEN
    RAISE EXCEPTION 'you cannot see who has access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- (the caller's settings are put back below; an error needs nothing put back: Postgres undoes these settings with
  -- the transaction, or the savepoint the error is caught at, as for explain, check_invariants and the logins)
  PERFORM set_config('authz.scopes', '', true);   -- each candidate is checked with full rights
  PERFORM set_config('authz.principal_type', '', true);   -- candidates are users
  <<asking>> BEGIN
  CASE p_type
    WHEN 'workspace' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."workspace__manage__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'manage_roles' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."workspace__manage_roles__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'work_all' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."workspace__work_all__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'work' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."workspace__work__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."workspace__view__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'impersonate' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."user__impersonate__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'see_notes' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."user__see_notes__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'org_tickets' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."user__org_tickets__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."user__view__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'integration' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage_keys' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."integration__manage_keys__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."integration__view__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'customer_org' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'see_tickets' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."customer_org__see_tickets__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'manage' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."customer_org__manage__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."customer_org__view__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'oversee' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."team__oversee__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'manage' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."team__manage__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."team__view__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'membership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."membership__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."membership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'leadership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."leadership__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."leadership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'support_grant' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."support_grant__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."support_grant__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'ticket' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'work' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."ticket__work__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'reply' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."ticket__reply__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."ticket__view__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'manage' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."ticket__manage__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'share' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."ticket__share__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'break_glass' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."ticket__break_glass__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'comment' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."comment__view__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "hd"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- Invariants: checked as everyone who can sign in (named as the audit trail names them: '42', 'user:a:b',
-- 'service:3') and as nobody; returns the violations
CREATE OR REPLACE FUNCTION authz.check_invariants() RETURNS TABLE (invariant text, user_id text, object_ids text[])
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_p text; v_u text; v_ids text[];
BEGIN
  PERFORM set_config('authz.scopes', '', true);
  FOR v_p, v_u IN SELECT '', '' UNION ALL SELECT '', x."id"::text FROM "hd"."users" x UNION ALL SELECT 'integration', x."id"::text FROM "hd"."integrations" x LOOP
    PERFORM set_config('authz.principal_type', v_p, true);
    PERFORM set_config('authz.user_id', v_u, true);
    PERFORM authz_int.sign();
    v_ids := ARRAY(SELECT id::text FROM authz_int."ticket__never__1" ORDER BY 1 LIMIT 5);
    IF cardinality(v_ids) > 0 THEN
      invariant := 'never ticket: view and not workspace.member and not responder and not workspace.connected (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'invariant never ticket: view and not workspace.member and not responder and not workspace.connected'), '?') || ')'; user_id := nullif(CASE WHEN coalesce(v_p, '') IN ('', 'user') THEN CASE WHEN pg_catalog.strpos(v_u, ':') > 0 OR v_u = 'nobody' THEN 'user:' || v_u ELSE v_u END ELSE v_p || ':' || v_u END, ''); object_ids := v_ids;
      RETURN NEXT;
    END IF;
    v_ids := ARRAY(SELECT id::text FROM authz_int."ticket__never__2" ORDER BY 1 LIMIT 5);
    IF cardinality(v_ids) > 0 THEN
      invariant := 'never ticket: work and not workspace.agent and not responder (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'invariant never ticket: work and not workspace.agent and not responder'), '?') || ')'; user_id := nullif(CASE WHEN coalesce(v_p, '') IN ('', 'user') THEN CASE WHEN pg_catalog.strpos(v_u, ':') > 0 OR v_u = 'nobody' THEN 'user:' || v_u ELSE v_u END ELSE v_p || ':' || v_u END, ''); object_ids := v_ids;
      RETURN NEXT;
    END IF;
    v_ids := ARRAY(SELECT id::text FROM authz_int."comment__never__3" ORDER BY 1 LIMIT 5);
    IF cardinality(v_ids) > 0 THEN
      invariant := 'never comment: view and not ticket.view (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'invariant never comment: view and not ticket.view'), '?') || ')'; user_id := nullif(CASE WHEN coalesce(v_p, '') IN ('', 'user') THEN CASE WHEN pg_catalog.strpos(v_u, ':') > 0 OR v_u = 'nobody' THEN 'user:' || v_u ELSE v_u END ELSE v_p || ':' || v_u END, ''); object_ids := v_ids;
      RETURN NEXT;
    END IF;
    v_ids := ARRAY(SELECT id::text FROM authz_int."user__never__4" ORDER BY 1 LIMIT 5);
    IF cardinality(v_ids) > 0 THEN
      invariant := 'never user: view and not self and not workspace.member and not workspace.connected (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'invariant never user: view and not self and not workspace.member and not workspace.connected'), '?') || ')'; user_id := nullif(CASE WHEN coalesce(v_p, '') IN ('', 'user') THEN CASE WHEN pg_catalog.strpos(v_u, ':') > 0 OR v_u = 'nobody' THEN 'user:' || v_u ELSE v_u END ELSE v_p || ':' || v_u END, ''); object_ids := v_ids;
      RETURN NEXT;
    END IF;
  END LOOP;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- Replace a group's members with the list your identity provider sends (administrators, sync jobs):
-- SELECT * FROM authz.sync_members('team', '10', 'member', ARRAY['1', '2'])
CREATE OR REPLACE FUNCTION authz.sync_members(p_type text, p_id text, p_relation text, p_members text[],
  OUT added int, OUT removed int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
BEGIN
  -- NULL is no list: it would remove every member (a sync job's failed fetch, a missing field)
  IF p_members IS NULL OR EXISTS (SELECT 1 FROM unnest(p_members) x WHERE x IS NULL) THEN
    RAISE EXCEPTION 'say who the members are: a list of ids with no NULL in it (an empty list for none)'
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  CASE p_type || '.' || p_relation
    WHEN 'workspace.member' THEN
      WITH want AS (SELECT DISTINCT x::uuid AS m FROM unnest($4) x),
      del AS (DELETE FROM "hd"."users" s WHERE s."workspace_id" = $2::uuid AND s."id" NOT IN (SELECT m FROM want) RETURNING 1),
      ins AS (INSERT INTO "hd"."users" ("workspace_id", "id") SELECT $2::uuid, w.m FROM want w
              WHERE NOT EXISTS (SELECT 1 FROM "hd"."users" s WHERE s."workspace_id" = $2::uuid AND s."id" = w.m) RETURNING 1)
      SELECT (SELECT count(*) FROM ins)::int, (SELECT count(*) FROM del)::int INTO added, removed;
    WHEN 'customer_org.member' THEN
      WITH want AS (SELECT DISTINCT x::uuid AS m FROM unnest($4) x),
      del AS (DELETE FROM "hd"."users" s WHERE s."customer_org_id" = $2::uuid AND s."id" NOT IN (SELECT m FROM want) RETURNING 1),
      ins AS (INSERT INTO "hd"."users" ("customer_org_id", "id") SELECT $2::uuid, w.m FROM want w
              WHERE NOT EXISTS (SELECT 1 FROM "hd"."users" s WHERE s."customer_org_id" = $2::uuid AND s."id" = w.m) RETURNING 1)
      SELECT (SELECT count(*) FROM ins)::int, (SELECT count(*) FROM del)::int INTO added, removed;
    WHEN 'team.member' THEN
      WITH want AS (SELECT DISTINCT x::uuid AS m FROM unnest($4) x),
      del AS (DELETE FROM "hd"."team_members" s WHERE s."team_id" = $2::uuid AND s."user_id" NOT IN (SELECT m FROM want) RETURNING 1),
      ins AS (INSERT INTO "hd"."team_members" ("team_id", "user_id") SELECT $2::uuid, w.m FROM want w
              WHERE NOT EXISTS (SELECT 1 FROM "hd"."team_members" s WHERE s."team_id" = $2::uuid AND s."user_id" = w.m) RETURNING 1)
      SELECT (SELECT count(*) FROM ins)::int, (SELECT count(*) FROM del)::int INTO added, removed;
    WHEN 'team.lead' THEN
      WITH want AS (SELECT DISTINCT x::uuid AS m FROM unnest($4) x),
      del AS (DELETE FROM "hd"."team_leads" s WHERE s."team_id" = $2::uuid AND s."user_id" NOT IN (SELECT m FROM want) RETURNING 1),
      ins AS (INSERT INTO "hd"."team_leads" ("team_id", "user_id") SELECT $2::uuid, w.m FROM want w
              WHERE NOT EXISTS (SELECT 1 FROM "hd"."team_leads" s WHERE s."team_id" = $2::uuid AND s."user_id" = w.m) RETURNING 1)
      SELECT (SELECT count(*) FROM ins)::int, (SELECT count(*) FROM del)::int INTO added, removed;
    ELSE RAISE EXCEPTION '%.% has no single table of members to sync (it needs one source: table(group -> user), without where)',
      p_type, p_relation USING HINT = 'rowstile help AZ707';
  END CASE;
  PERFORM authz_int.audit('sync_members', p_type, authz_int.canon(p_type, p_id), p_relation, 'user', NULL, NULL,
                          jsonb_build_object('added', added, 'removed', removed, 'members', p_members));
END $f$;

-- the API keys of user rows that are gone, or whose id changed, are deleted (authz_int.keys_gone)
CREATE OR REPLACE FUNCTION authz_int."user__keys_gone"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    IF NOT EXISTS (SELECT 1 FROM "hd"."users") THEN   -- the table is empty, and so are those under it
      PERFORM authz_int.keys_gone('user', NULL);
    ELSE   -- TRUNCATE ONLY, or of a table under it: the rows still there keep their keys
      PERFORM authz_int.keys_gone('user', ARRAY(SELECT k.user_id FROM authz.api_keys k WHERE k.principal_type = 'user'
                                                AND NOT EXISTS (SELECT 1 FROM "hd"."users" x WHERE x."id"::text = k.user_id)));
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

-- the API keys of integration rows that are gone, or whose id changed, are deleted (authz_int.keys_gone)
CREATE OR REPLACE FUNCTION authz_int."integration__keys_gone"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    IF NOT EXISTS (SELECT 1 FROM "hd"."integrations") THEN   -- the table is empty, and so are those under it
      PERFORM authz_int.keys_gone('integration', NULL);
    ELSE   -- TRUNCATE ONLY, or of a table under it: the rows still there keep their keys
      PERFORM authz_int.keys_gone('integration', ARRAY(SELECT k.user_id FROM authz.api_keys k WHERE k.principal_type = 'integration'
                                                AND NOT EXISTS (SELECT 1 FROM "hd"."integrations" x WHERE x."id"::text = k.user_id)));
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.keys_gone('integration', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.keys_gone('integration', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

-- what reads the objects a transaction changed, and what reads those, to the end (no limit: each is worked out again)
CREATE OR REPLACE FUNCTION authz_int.sync_spread(p_tx bigint, p_round int) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE r int := p_round; n bigint;
BEGIN
  LOOP
    INSERT INTO authz_int.sync_todo (txid, type, id, round)
    SELECT $1, d.t, d.i, authz__.r + 1 FROM (
      SELECT 'ticket'::text AS t, v.id::text AS i FROM (SELECT x."id"::text FROM "hd"."tickets" x WHERE x."workspace_id" IN (SELECT unnest(ARRAY(SELECT v::uuid FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'workspace' AND x.round = authz__.r AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))))) v(id)
      UNION ALL SELECT 'ticket'::text, '*'::text WHERE EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'workspace' AND x.round = authz__.r AND x.id = '*')
      UNION ALL SELECT 'ticket'::text AS t, v.id::text AS i FROM (SELECT x."id"::text FROM "hd"."tickets" x WHERE x."requester_id" IN (SELECT unnest(ARRAY(SELECT v::uuid FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'user' AND x.round = authz__.r AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))))) v(id)
      UNION ALL SELECT 'ticket'::text, '*'::text WHERE EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'user' AND x.round = authz__.r AND x.id = '*')
      UNION ALL SELECT 'user'::text AS t, v.id::text AS i FROM (SELECT x."id"::text FROM "hd"."users" x WHERE x."customer_org_id" IN (SELECT unnest(ARRAY(SELECT v::uuid FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'customer_org' AND x.round = authz__.r AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))))) v(id)
      UNION ALL SELECT 'user'::text, '*'::text WHERE EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'customer_org' AND x.round = authz__.r AND x.id = '*')
      UNION ALL SELECT 'comment'::text AS t, v.id::text AS i FROM (SELECT x."id"::text FROM "hd"."comments" x WHERE x."ticket_id" IN (SELECT unnest(ARRAY(SELECT v::uuid FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'ticket' AND x.round = authz__.r AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))))) v(id)
      UNION ALL SELECT 'comment'::text, '*'::text WHERE EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'ticket' AND x.round = authz__.r AND x.id = '*')
      UNION ALL SELECT 'team'::text AS t, v.id::text AS i FROM (SELECT c.descendant::text FROM authz_int."team__parent__tree" c WHERE c.ancestor IN (SELECT unnest(ARRAY(SELECT v::uuid FROM unnest(ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'team' AND x.round = authz__.r AND x.id <> '*')) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))))) v(id)
      UNION ALL SELECT 'team'::text, '*'::text WHERE EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = $1 AND x.type = 'team' AND x.round = authz__.r AND x.id = '*')) d WHERE d.i IS NOT NULL
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0 AND NOT EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = p_tx AND x.round > r);
    r := r + 1;
  END LOOP;
  RETURN r;
END $f$;

-- The index made current for the objects a transaction changed and what reads them (the difference written, not
-- every row again): at its commit, in it, or after it, by the worker. The groups first, then the keys (a principal
-- holds the keys of every group whose members hold one of its own, through groups inside groups), then the readers
-- (JIT off: its statements read a few rows each, through indexes, which a plan made for many would compile for; no
-- merge joins: its sets of keys, which the planner can't count, are joined by hash, not sorted as text)
CREATE OR REPLACE FUNCTION authz_int.sync_process() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET jit = off SET enable_mergejoin = off AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE
  v_tx bigint := txid_current();
  v_round int;
  v_mode int[]; v_w int[]; v_r int[]; v_s int; v_x boolean; v_hi int; v_nowait boolean := false;
  v_ids text[]; v_part text[]; v_from int; v_now text[];
  v_keys text[] := '{}';     -- the keys a principal gained or lost
  v_came text[] := '{}';     -- the principals who are somebody now, and held no key (type:id)
  v_whole text[] := '{}';    -- the principal types worked out whole
  v_keys_locked boolean := false;
  v_all boolean;               -- every principal's keys worked out whole (applying): the groups' changes aren't followed
  v_n bigint;
  v_found int;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx) THEN RETURN; END IF;
  -- one lock row for every commit's work: what an `and` or `not` between parts that depend on who asks
  -- gives is worked out from the keys, which any change may move. In REPEATABLE READ or SERIALIZABLE, a
  -- writer whose snapshot is older than another's index write gets a serialization error
  UPDATE authz_int.locks SET n = n + 1 WHERE type = 'sync#keys';
  v_keys_locked := true;
  v_round := authz_int.sync_spread(v_tx, 0);
  v_all := (SELECT count(DISTINCT x.type) FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.id = '*'
            AND x.type = ANY (ARRAY['user', 'integration']::text[])) = 2;
  -- team's groups
  v_ids := CASE WHEN EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'team' AND x.id = '*') THEN ARRAY(SELECT x."id"::text FROM "hd"."teams" x UNION SELECT x."team_id"::text FROM "hd"."team_members" x UNION SELECT x."team_id"::text FROM "hd"."team_leads" x UNION SELECT g.object_id FROM authz.shares g WHERE g.object_type = 'team' UNION SELECT substr(g.grp, strpos(g.grp, ':') + 1) FROM authz_sync.groups g WHERE left(g.grp, strpos(g.grp, ':')) = ANY (ARRAY['team#member:', 'team#oversee:']::text[])) ELSE ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'team') END;
  FOR v_from IN 1 .. coalesce(cardinality(v_ids), 0) BY 10000 LOOP
    v_part := v_ids[v_from : v_from + 9999];
      WITH fresh AS MATERIALIZED (SELECT 'team#member:' || f.o_id::text AS grp, f.o_key AS key FROM authz_int."sync:team.member"(ARRAY(SELECT v::uuid FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) f WHERE NOT f.o_dep),
      gone AS (DELETE FROM authz_sync.groups g WHERE g.grp IN (SELECT 'team#member:' || v FROM unnest(v_part) v)
               AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.grp = g.grp AND f.key = g.key) RETURNING g.grp, g.key),
      made AS (INSERT INTO authz_sync.groups SELECT f.grp, f.key FROM fresh f ON CONFLICT DO NOTHING RETURNING grp, key)
      INSERT INTO authz_int.sync_moved SELECT v_tx, z.grp, z.key, z.made
      FROM (SELECT grp, key, false AS made FROM gone UNION ALL SELECT grp, key, true FROM made) z
      WHERE NOT v_all;
      WITH fresh AS MATERIALIZED (SELECT 'team#oversee:' || f.o_id::text AS grp, f.o_key AS key FROM authz_int."sync:team.oversee"(ARRAY(SELECT v::uuid FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) f WHERE NOT f.o_dep),
      gone AS (DELETE FROM authz_sync.groups g WHERE g.grp IN (SELECT 'team#oversee:' || v FROM unnest(v_part) v)
               AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.grp = g.grp AND f.key = g.key) RETURNING g.grp, g.key),
      made AS (INSERT INTO authz_sync.groups SELECT f.grp, f.key FROM fresh f ON CONFLICT DO NOTHING RETURNING grp, key)
      INSERT INTO authz_int.sync_moved SELECT v_tx, z.grp, z.key, z.made
      FROM (SELECT grp, key, false AS made FROM gone UNION ALL SELECT grp, key, true FROM made) z
      WHERE NOT v_all;
  END LOOP;
  -- the keys, where the groups' rows or the principals changed: under one lock row, taken last (nothing after it waits
  -- for another lock)
  IF EXISTS (SELECT 1 FROM authz_int.sync_moved m WHERE m.txid = v_tx)
     OR EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = ANY (ARRAY['user', 'integration']::text[])) THEN
    IF NOT v_keys_locked THEN
      UPDATE authz_int.locks SET n = n + 1 WHERE type = 'sync#keys';
    END IF;
    -- the principals of user: every one worked out whole (applying), or those that changed: one who is
    -- nobody now (gone, or failing the type's where) holds no key, and one who is somebody now and held none gets theirs
    IF EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'user' AND x.id = '*') THEN
      v_whole := v_whole || 'user'::text;
      v_ids := ARRAY(SELECT x."id"::text FROM "hd"."users" x UNION SELECT k.principal_id FROM authz_sync.keys k WHERE k.principal_type = 'user');
      WITH fresh AS MATERIALIZED (SELECT * FROM authz_int."sync_keys:user"(v_ids)),
      gone AS (DELETE FROM authz_sync.keys k WHERE k.principal_type = 'user' AND k.principal_id IN (SELECT unnest(v_ids))
               AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_id = k.principal_id AND f.o_key = k.key) RETURNING k.key),
      made AS (INSERT INTO authz_sync.keys SELECT 'user', f.o_id, f.o_key FROM fresh f ON CONFLICT DO NOTHING RETURNING key)
      SELECT v_keys || coalesce(array_agg(DISTINCT z.k), '{}') INTO v_keys FROM (SELECT key FROM gone UNION SELECT key FROM made) z(k);
    ELSE
      v_ids := ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'user');
      IF cardinality(v_ids) > 0 THEN
        v_now := ARRAY(SELECT x."id"::text FROM "hd"."users" x WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::uuid FROM unnest(authz__.v_ids) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid')))) AND coalesce((active), false));
        WITH gone AS (DELETE FROM authz_sync.keys k WHERE k.principal_type = 'user' AND k.principal_id = ANY (v_ids)
                      AND k.principal_id <> ALL (v_now) RETURNING k.key)
        SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM gone z;
        v_came := v_came || ARRAY(SELECT 'user' || ':' || v FROM unnest(v_now) v WHERE NOT EXISTS (
          SELECT 1 FROM authz_sync.keys k WHERE k.principal_type = 'user' AND k.principal_id = v));
      END IF;
    END IF;
    -- the principals of integration: every one worked out whole (applying), or those that changed: one who is
    -- nobody now (gone, or failing the type's where) holds no key, and one who is somebody now and held none gets theirs
    IF EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'integration' AND x.id = '*') THEN
      v_whole := v_whole || 'integration'::text;
      v_ids := ARRAY(SELECT x."id"::text FROM "hd"."integrations" x UNION SELECT k.principal_id FROM authz_sync.keys k WHERE k.principal_type = 'integration');
      WITH fresh AS MATERIALIZED (SELECT * FROM authz_int."sync_keys:integration"(v_ids)),
      gone AS (DELETE FROM authz_sync.keys k WHERE k.principal_type = 'integration' AND k.principal_id IN (SELECT unnest(v_ids))
               AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_id = k.principal_id AND f.o_key = k.key) RETURNING k.key),
      made AS (INSERT INTO authz_sync.keys SELECT 'integration', f.o_id, f.o_key FROM fresh f ON CONFLICT DO NOTHING RETURNING key)
      SELECT v_keys || coalesce(array_agg(DISTINCT z.k), '{}') INTO v_keys FROM (SELECT key FROM gone UNION SELECT key FROM made) z(k);
    ELSE
      v_ids := ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'integration');
      IF cardinality(v_ids) > 0 THEN
        v_now := ARRAY(SELECT x."id"::text FROM "hd"."integrations" x WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::uuid FROM unnest(authz__.v_ids) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid')))) AND coalesce((active), false));
        WITH gone AS (DELETE FROM authz_sync.keys k WHERE k.principal_type = 'integration' AND k.principal_id = ANY (v_ids)
                      AND k.principal_id <> ALL (v_now) RETURNING k.key)
        SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM gone z;
        v_came := v_came || ARRAY(SELECT 'integration' || ':' || v FROM unnest(v_now) v WHERE NOT EXISTS (
          SELECT 1 FROM authz_sync.keys k WHERE k.principal_type = 'integration' AND k.principal_id = v));
      END IF;
    END IF;
    -- a group's row gone: the keys above it that its member's holders held may go, unless what is left gives them
    -- again (each found given is taken back from those that may go, as often as it finds more)
    IF EXISTS (SELECT 1 FROM authz_int.sync_moved m WHERE m.txid = v_tx AND NOT m.made) THEN
      WITH RECURSIVE up(src, c) AS (
        SELECT DISTINCT m.key, m.grp FROM authz_int.sync_moved m WHERE m.txid = v_tx AND NOT m.made
        UNION
        SELECT up.src, g.grp FROM up JOIN authz_sync.groups g ON g.key = up.c)
      -- (the holders of each key, a lookup by the keys' index: OFFSET 0 keeps the planner from reading every key for a
      -- few; then the sets joined whole)
      , by_src AS MATERIALIZED (
        SELECT DISTINCT up.c, k.principal_type AS pt, k.principal_id AS pid FROM up
        CROSS JOIN LATERAL (SELECT k.principal_type, k.principal_id FROM authz_sync.keys k WHERE k.key = up.src
                            AND k.principal_type <> ALL (v_whole) OFFSET 0) k),
      by_c AS MATERIALIZED (
        SELECT c.c, h.principal_type AS pt, h.principal_id AS pid FROM (SELECT DISTINCT up.c FROM up) c
        CROSS JOIN LATERAL (SELECT h.principal_type, h.principal_id FROM authz_sync.keys h WHERE h.key = c.c OFFSET 0) h)
      INSERT INTO authz_int.sync_lost (txid, ptype, pid, key)
      SELECT v_tx, s.pt, s.pid, s.c FROM by_src s JOIN by_c h ON h.c = s.c AND h.pt = s.pt AND h.pid = s.pid
      ON CONFLICT DO NOTHING;
      -- given again: by a member it holds that may not go (the holders of the members of the groups that may go, once
      -- each); then, round by round, by a member just found given
      WITH members AS MATERIALIZED (
        SELECT g.grp, g.key FROM (SELECT DISTINCT l.key FROM authz_int.sync_lost l WHERE l.txid = v_tx) c
        CROSS JOIN LATERAL (SELECT g.grp, g.key FROM authz_sync.groups g WHERE g.grp = c.key OFFSET 0) g),
      held AS MATERIALIZED (
        SELECT m.key, h.principal_type AS pt, h.principal_id AS pid FROM (SELECT DISTINCT key FROM members) m
        CROSS JOIN LATERAL (SELECT h.principal_type, h.principal_id FROM authz_sync.keys h WHERE h.key = m.key OFFSET 0) h),
      -- (the groups each holder holds a member of, that may not go; then the candidates they give again)
      supported AS MATERIALIZED (
        SELECT DISTINCT g.grp, h.pt, h.pid FROM members g JOIN held h ON h.key = g.key
        WHERE NOT EXISTS (SELECT 1 FROM authz_int.sync_lost o WHERE o.txid = v_tx AND o.ptype = h.pt AND o.pid = h.pid
                          AND o.key = h.key)),
      given AS (SELECT l.ptype, l.pid, l.key FROM authz_int.sync_lost l
                JOIN supported s ON s.grp = l.key AND s.pt = l.ptype AND s.pid = l.pid WHERE l.txid = v_tx),
      r AS (DELETE FROM authz_int.sync_lost l USING given z WHERE l.txid = v_tx AND l.ptype = z.ptype AND l.pid = z.pid
            AND l.key = z.key RETURNING l.ptype, l.pid, l.key)
      INSERT INTO authz_int.sync_found SELECT v_tx, r.ptype, r.pid, r.key, 1 FROM r;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_found := 1;
      WHILE v_n > 0 LOOP
        WITH r AS (DELETE FROM authz_int.sync_lost l
                   USING (SELECT DISTINCT f.ptype, f.pid, g.grp FROM authz_int.sync_found f
                          JOIN authz_sync.groups g ON g.key = f.key WHERE f.txid = v_tx AND f.round = v_found) z
                   WHERE l.txid = v_tx AND l.ptype = z.ptype AND l.pid = z.pid AND l.key = z.grp
                   RETURNING l.ptype, l.pid, l.key)
        INSERT INTO authz_int.sync_found SELECT v_tx, r.ptype, r.pid, r.key, v_found + 1 FROM r;
        GET DIAGNOSTICS v_n = ROW_COUNT;
        v_found := v_found + 1;
      END LOOP;
      DELETE FROM authz_int.sync_found f WHERE f.txid = v_tx;
      WITH gone AS (DELETE FROM authz_sync.keys k USING authz_int.sync_lost l WHERE l.txid = v_tx
                    AND k.principal_type = l.ptype AND k.principal_id = l.pid AND k.key = l.key RETURNING k.key)
      SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM gone z;
      DELETE FROM authz_int.sync_lost l WHERE l.txid = v_tx;
    END IF;
    -- a group's row made: its member's holders hold the group, and the groups above it
    IF EXISTS (SELECT 1 FROM authz_int.sync_moved m WHERE m.txid = v_tx AND m.made) THEN
      WITH RECURSIVE up(src, c) AS (
        SELECT DISTINCT m.key, m.grp FROM authz_int.sync_moved m WHERE m.txid = v_tx AND m.made
        UNION
        SELECT up.src, g.grp FROM up JOIN authz_sync.groups g ON g.key = up.c),
      made AS (INSERT INTO authz_sync.keys SELECT DISTINCT k.principal_type, k.principal_id, up.c FROM up
               CROSS JOIN LATERAL (SELECT k.principal_type, k.principal_id FROM authz_sync.keys k WHERE k.key = up.src
                                   AND k.principal_type <> ALL (v_whole) OFFSET 0) k
               ON CONFLICT DO NOTHING RETURNING key)
      SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM made z;
    END IF;
    DELETE FROM authz_int.sync_moved m WHERE m.txid = v_tx;
    -- the principals who are somebody now: their keys, worked out whole
    IF cardinality(v_came) > 0 THEN
    WITH made AS (INSERT INTO authz_sync.keys SELECT 'user', f.o_id, f.o_key FROM authz_int."sync_keys:user"(ARRAY(
                    SELECT substr(c, 6) FROM unnest(v_came) c WHERE left(c, 5) = 'user:')) f
                  ON CONFLICT DO NOTHING RETURNING key)
    SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM made z;
    WITH made AS (INSERT INTO authz_sync.keys SELECT 'integration', f.o_id, f.o_key FROM authz_int."sync_keys:integration"(ARRAY(
                    SELECT substr(c, 13) FROM unnest(v_came) c WHERE left(c, 12) = 'integration:')) f
                  ON CONFLICT DO NOTHING RETURNING key)
    SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM made z;
    END IF;
  END IF;
  -- rows whose readers were worked out from a key someone gained or lost, and what reads them
  IF cardinality(v_keys) > 0 THEN
    INSERT INTO authz_int.sync_todo (txid, type, id, round)
    SELECT DISTINCT v_tx, x.object_type, x.object_id, v_round + 1 FROM authz_sync.expanded x WHERE x.key IN (SELECT unnest(v_keys))
    ON CONFLICT DO NOTHING;
    IF FOUND THEN
      v_round := authz_int.sync_spread(v_tx, v_round + 1);
    END IF;
  END IF;
  -- ticket's readers
  v_ids := CASE WHEN EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'ticket' AND x.id = '*') THEN ARRAY(SELECT x."id"::text FROM "hd"."tickets" x UNION SELECT x."id"::text FROM authz_sync."ticket__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'ticket') ELSE ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'ticket') END;
  -- (a batch of objects at a time, which a comparison holds in memory; what is there compared first, by the key's
  -- index: only the rows that change are visited)
  FOR v_from IN 1 .. coalesce(cardinality(v_ids), 0) BY 10000 LOOP
    v_part := v_ids[v_from : v_from + 9999];
    WITH fresh AS MATERIALIZED (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:ticket"(ARRAY(SELECT v::uuid FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) f),
    there AS MATERIALIZED (SELECT x."id" AS id, x.key FROM authz_sync."ticket__readers" x
                           WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::uuid FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) AS id)),
    stale AS (SELECT s.id, s.key FROM there s EXCEPT SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep),
    added AS (SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep EXCEPT SELECT s.id, s.key FROM there s),
    gone AS (DELETE FROM authz_sync."ticket__readers" x USING stale s WHERE x."id" = s.id AND x.key = s.key
             RETURNING 1),
    made AS (INSERT INTO authz_sync."ticket__readers" SELECT a.o_id, a.o_key FROM added a
             ORDER BY 1, 2 ON CONFLICT DO NOTHING RETURNING 1),
    gone_from AS (DELETE FROM authz_sync.expanded x WHERE x.object_type = 'ticket' AND x.object_id IN (SELECT unnest(v_part))
             AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_dep AND f.o_id::text = x.object_id AND f.o_key = x.key) RETURNING 1),
    made_from AS (INSERT INTO authz_sync.expanded SELECT 'ticket', f.o_id::text, f.o_key FROM fresh f WHERE f.o_dep ON CONFLICT DO NOTHING RETURNING 1)
    SELECT count(*) INTO v_n FROM (SELECT 1 FROM gone UNION ALL SELECT 1 FROM made UNION ALL SELECT 1 FROM gone_from
                                   UNION ALL SELECT 1 FROM made_from) z;
  END LOOP;
  -- comment's readers
  v_ids := CASE WHEN EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'comment' AND x.id = '*') THEN ARRAY(SELECT x."id"::text FROM "hd"."comments" x UNION SELECT x."id"::text FROM authz_sync."comment__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'comment') ELSE ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = authz__.v_tx AND x.type = 'comment') END;
  -- (a batch of objects at a time, which a comparison holds in memory; what is there compared first, by the key's
  -- index: only the rows that change are visited)
  FOR v_from IN 1 .. coalesce(cardinality(v_ids), 0) BY 10000 LOOP
    v_part := v_ids[v_from : v_from + 9999];
    WITH fresh AS MATERIALIZED (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:comment"(ARRAY(SELECT v::uuid FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) f),
    there AS MATERIALIZED (SELECT x."id" AS id, x.key FROM authz_sync."comment__readers" x
                           WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::uuid FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) AS id)),
    stale AS (SELECT s.id, s.key FROM there s EXCEPT SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep),
    added AS (SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep EXCEPT SELECT s.id, s.key FROM there s),
    gone AS (DELETE FROM authz_sync."comment__readers" x USING stale s WHERE x."id" = s.id AND x.key = s.key
             RETURNING 1),
    made AS (INSERT INTO authz_sync."comment__readers" SELECT a.o_id, a.o_key FROM added a
             ORDER BY 1, 2 ON CONFLICT DO NOTHING RETURNING 1),
    gone_from AS (DELETE FROM authz_sync.expanded x WHERE x.object_type = 'comment' AND x.object_id IN (SELECT unnest(v_part))
             AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_dep AND f.o_id::text = x.object_id AND f.o_key = x.key) RETURNING 1),
    made_from AS (INSERT INTO authz_sync.expanded SELECT 'comment', f.o_id::text, f.o_key FROM fresh f WHERE f.o_dep ON CONFLICT DO NOTHING RETURNING 1)
    SELECT count(*) INTO v_n FROM (SELECT 1 FROM gone UNION ALL SELECT 1 FROM made UNION ALL SELECT 1 FROM gone_from
                                   UNION ALL SELECT 1 FROM made_from) z;
  END LOOP;
  -- the next start or end of a share on what was worked out, after now(), when authz.sync_tick() works it out again
  -- (the work reads the shares as of the transaction's start: one that starts or ends while it is open, and a tick
  -- meanwhile, which can't see what it hasn't committed, are worked out again at the next tick)
  v_ids := ARRAY(SELECT DISTINCT x.type FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.id = '*');
  WITH w AS MATERIALIZED (SELECT x.type, x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.id <> '*'
                          AND x.type <> ALL (v_ids)),
  fresh AS MATERIALIZED (
    SELECT w.type, w.id, b.at FROM w
    CROSS JOIN LATERAL (SELECT min(v.at) AS at FROM authz.shares g CROSS JOIN LATERAL (VALUES (g.starts_at), (g.expires_at)) v(at)
                        WHERE g.object_type = w.type AND g.object_id = w.id AND v.at > now()) b
    WHERE b.at IS NOT NULL
    UNION ALL
    SELECT g.object_type, g.object_id, min(v.at) FROM authz.shares g CROSS JOIN LATERAL (VALUES (g.starts_at), (g.expires_at)) v(at)
    WHERE g.object_type = ANY (v_ids) AND v.at > now() GROUP BY g.object_type, g.object_id),
  gone AS (DELETE FROM authz_sync.due d USING w WHERE d.object_type = w.type AND d.object_id = w.id
           AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.type = d.object_type AND f.id = d.object_id) RETURNING 1),
  gone_all AS (DELETE FROM authz_sync.due d WHERE d.object_type = ANY (v_ids)
           AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.type = d.object_type AND f.id = d.object_id) RETURNING 1)
  INSERT INTO authz_sync.due SELECT f.type, f.id, f.at FROM fresh f
  ON CONFLICT (object_type, object_id) DO UPDATE SET at = EXCLUDED.at WHERE authz_sync.due.at <> EXCLUDED.at;
  DELETE FROM authz_int.sync_todo x WHERE x.txid = v_tx;
END $f$;

-- Admin check: the sync index matches a rebuild (false says which part differs, in a notice)
CREATE OR REPLACE FUNCTION authz.sync_verify() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
  IF EXISTS (
    WITH s AS MATERIALIZED (SELECT grp, key FROM authz_sync.groups), f AS MATERIALIZED (SELECT 'team#member:' || f.o_id::text AS grp, f.o_key AS key FROM authz_int."sync:team.member"(ARRAY(SELECT v::uuid FROM unnest(ARRAY(SELECT x."id"::text FROM "hd"."teams" x UNION SELECT x."team_id"::text FROM "hd"."team_members" x UNION SELECT x."team_id"::text FROM "hd"."team_leads" x UNION SELECT g.object_id FROM authz.shares g WHERE g.object_type = 'team' UNION SELECT substr(g.grp, strpos(g.grp, ':') + 1) FROM authz_sync.groups g WHERE left(g.grp, strpos(g.grp, ':')) = ANY (ARRAY['team#member:', 'team#oversee:']::text[]))) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) f WHERE NOT f.o_dep UNION SELECT 'team#oversee:' || f.o_id::text AS grp, f.o_key AS key FROM authz_int."sync:team.oversee"(ARRAY(SELECT v::uuid FROM unnest(ARRAY(SELECT x."id"::text FROM "hd"."teams" x UNION SELECT x."team_id"::text FROM "hd"."team_members" x UNION SELECT x."team_id"::text FROM "hd"."team_leads" x UNION SELECT g.object_id FROM authz.shares g WHERE g.object_type = 'team' UNION SELECT substr(g.grp, strpos(g.grp, ':') + 1) FROM authz_sync.groups g WHERE left(g.grp, strpos(g.grp, ':')) = ANY (ARRAY['team#member:', 'team#oversee:']::text[]))) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) f WHERE NOT f.o_dep)
    SELECT 1 FROM ((TABLE s EXCEPT TABLE f) UNION ALL (TABLE f EXCEPT TABLE s)) d) THEN
    RAISE NOTICE 'the sync index differs from a rebuild: %', 'groups';
    RETURN false;
  END IF;
  IF EXISTS (
    WITH s AS MATERIALIZED (SELECT principal_type, principal_id, key FROM authz_sync.keys), f AS MATERIALIZED (SELECT 'user'::text, f.o_id, f.o_key FROM authz_int."sync_keys:user"(ARRAY(SELECT x."id"::text FROM "hd"."users" x UNION SELECT k.principal_id FROM authz_sync.keys k WHERE k.principal_type = 'user')) f UNION SELECT 'integration'::text, f.o_id, f.o_key FROM authz_int."sync_keys:integration"(ARRAY(SELECT x."id"::text FROM "hd"."integrations" x UNION SELECT k.principal_id FROM authz_sync.keys k WHERE k.principal_type = 'integration')) f)
    SELECT 1 FROM ((TABLE s EXCEPT TABLE f) UNION ALL (TABLE f EXCEPT TABLE s)) d) THEN
    RAISE NOTICE 'the sync index differs from a rebuild: %', 'keys';
    RETURN false;
  END IF;
  IF EXISTS (
    WITH s AS MATERIALIZED (SELECT x."id"::text, x.key, false FROM authz_sync."ticket__readers" x UNION ALL SELECT x.object_id, x.key, true FROM authz_sync.expanded x WHERE x.object_type = 'ticket'), f AS MATERIALIZED (SELECT f.o_id::text, f.o_key, f.o_dep FROM (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:ticket"(ARRAY(SELECT v::uuid FROM unnest(ARRAY(SELECT x."id"::text FROM "hd"."tickets" x UNION SELECT x."id"::text FROM authz_sync."ticket__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'ticket')) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) f) f)
    SELECT 1 FROM ((TABLE s EXCEPT TABLE f) UNION ALL (TABLE f EXCEPT TABLE s)) d) THEN
    RAISE NOTICE 'the sync index differs from a rebuild: %', 'ticket''s readers, and what they were worked out from';
    RETURN false;
  END IF;
  IF EXISTS (
    WITH s AS MATERIALIZED (SELECT x."id"::text, x.key, false FROM authz_sync."comment__readers" x UNION ALL SELECT x.object_id, x.key, true FROM authz_sync.expanded x WHERE x.object_type = 'comment'), f AS MATERIALIZED (SELECT f.o_id::text, f.o_key, f.o_dep FROM (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:comment"(ARRAY(SELECT v::uuid FROM unnest(ARRAY(SELECT x."id"::text FROM "hd"."comments" x UNION SELECT x."id"::text FROM authz_sync."comment__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'comment')) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) f) f)
    SELECT 1 FROM ((TABLE s EXCEPT TABLE f) UNION ALL (TABLE f EXCEPT TABLE s)) d) THEN
    RAISE NOTICE 'the sync index differs from a rebuild: %', 'comment''s readers, and what they were worked out from';
    RETURN false;
  END IF;
  RETURN true;
END $f$;

-- The partitions of each table with rules and the tables that inherit from one: row-level security on, with
-- no policies of their own, so they are read and written through it only (read directly, they would skip its rules
-- and triggers). Every apply and every migration: one made or attached since is closed too (it alone is locked,
-- as CHILD_TRIGGERS locks only one that lacks the triggers)
DO $rls$
DECLARE c regclass;
BEGIN
  FOR c IN WITH RECURSIVE d(oid) AS (
             SELECT i.inhrelid FROM pg_catalog.pg_inherits i
             WHERE i.inhparent = ANY (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"hd"."comments"', '"hd"."customer_orgs"', '"hd"."integrations"', '"hd"."support_access"', '"hd"."team_leads"', '"hd"."team_members"', '"hd"."teams"', '"hd"."tickets"', '"hd"."users"', '"hd"."workspaces"']::text[]) x)
             UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass FROM d JOIN pg_catalog.pg_class k ON k.oid = d.oid WHERE NOT k.relrowsecurity LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', c);
  END LOOP;
END $rls$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

-- The sync role reads the index, and nothing else rowstile keeps
DO $sr$
DECLARE v_sync oid := to_regrole('"hd_electric"'); v_app oid := to_regrole('"hd_app"'); v_cols text;
BEGIN
  IF v_sync IS NULL THEN
    RAISE EXCEPTION 'the sync role hd_electric does not exist [AZ808]'
      USING HINT = 'make it for the engine: CREATE ROLE hd_electric LOGIN REPLICATION BYPASSRLS, then apply again';
  END IF;
  IF (SELECT r.rolsuper FROM pg_catalog.pg_roles r WHERE r.oid = v_sync) THEN
    RAISE EXCEPTION 'the sync role hd_electric is a superuser, which may turn row-level security off and change the rules [AZ808]'
      USING HINT = 'the engine connects as a role of its own: CREATE ROLE sync_engine LOGIN REPLICATION BYPASSRLS';
  END IF;
  IF pg_catalog.pg_has_role(v_sync, CURRENT_USER, 'MEMBER') THEN
    RAISE EXCEPTION 'the sync role hd_electric is the role that applies the policy (%), or a member of it [AZ808]', CURRENT_USER
      USING HINT = 'the engine connects as a role of its own, which owns nothing of the database';
  END IF;
  IF v_app IS NOT NULL AND (pg_catalog.pg_has_role(v_sync, v_app, 'MEMBER') OR pg_catalog.pg_has_role(v_app, v_sync, 'MEMBER')) THEN
    RAISE EXCEPTION 'the sync role hd_electric and the app role hd_app are one another''s members: the app would read every row [AZ808]'
      USING HINT = 'the engine connects as a role of its own, which the app role is not a member of, nor it of the app role';
  END IF;
  SELECT pg_catalog.string_agg(m.tbl || '.' || m.col, ', ' ORDER BY m.tbl, m.col) INTO v_cols FROM authz_int.masked_columns m
  WHERE pg_catalog.has_column_privilege(v_sync, m.tbl, m.col, 'SELECT');
  IF v_cols IS NOT NULL THEN
    RAISE EXCEPTION 'the sync role hd_electric may read masked columns: % [AZ809]', v_cols
      USING HINT = 'it reads every row, so a masked column would reach every client: revoke SELECT on the table, grant the other columns (GRANT SELECT (id, name) ON ...), then apply again';
  END IF;
END $sr$;
GRANT USAGE ON SCHEMA authz_sync TO "hd_electric";
GRANT SELECT ON ALL TABLES IN SCHEMA authz_sync TO "hd_electric";

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"hd_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"hd_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."customer_org__member"', 'authz_int."team__lead"', 'authz_int."team__manage"', 'authz_int."team__member"', 'authz_int."team__oversee"', 'authz_int."team__view"', 'authz_int."ticket__cc"', 'authz_int."ticket__reply"', 'authz_int."ticket__responder"', 'authz_int."ticket__roles:work"', 'authz_int."ticket__view"', 'authz_int."ticket__work"', 'authz_int."user__org_tickets"', 'authz_int."user__self"', 'authz_int."workspace__admin"', 'authz_int."workspace__agent"', 'authz_int."workspace__connected"', 'authz_int."workspace__manage"', 'authz_int."workspace__member"', 'authz_int."workspace__view"', 'authz_int."workspace__work"', 'authz_int."workspace__work_all"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"hd_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"hd_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"hd.comments:delete:items"', '"hd.comments:delete:why"', '"hd.comments:insert:items"', '"hd.comments:insert:refuse"', '"hd.comments:insert:why"', '"hd.comments:rules:explain"', '"hd.comments:update:items"', '"hd.comments:update:refuse"', '"hd.comments:update:why"', '"hd.customer_orgs:column id, workspace_id:items"', '"hd.customer_orgs:column id, workspace_id:why"', '"hd.customer_orgs:delete:items"', '"hd.customer_orgs:delete:why"', '"hd.customer_orgs:insert:items"', '"hd.customer_orgs:insert:refuse"', '"hd.customer_orgs:insert:why"', '"hd.customer_orgs:rules:explain"', '"hd.customer_orgs:update:items"', '"hd.customer_orgs:update:refuse"', '"hd.customer_orgs:update:why"', '"hd.integrations:column id, workspace_id:items"', '"hd.integrations:column id, workspace_id:why"', '"hd.integrations:delete:items"', '"hd.integrations:delete:why"', '"hd.integrations:insert:items"', '"hd.integrations:insert:refuse"', '"hd.integrations:insert:why"', '"hd.integrations:rules:explain"', '"hd.integrations:update:items"', '"hd.integrations:update:refuse"', '"hd.integrations:update:why"', '"hd.support_access:delete:items"', '"hd.support_access:delete:why"', '"hd.support_access:insert:items"', '"hd.support_access:insert:refuse"', '"hd.support_access:insert:why"', '"hd.support_access:rules:explain"', '"hd.support_access:update:items"', '"hd.support_access:update:refuse"', '"hd.support_access:update:why"', '"hd.team_leads:delete:items"', '"hd.team_leads:delete:why"', '"hd.team_leads:insert:items"', '"hd.team_leads:insert:refuse"', '"hd.team_leads:insert:why"', '"hd.team_leads:rules:explain"', '"hd.team_leads:update:items"', '"hd.team_leads:update:refuse"', '"hd.team_leads:update:why"', '"hd.team_members:delete:items"', '"hd.team_members:delete:why"', '"hd.team_members:insert:items"', '"hd.team_members:insert:refuse"', '"hd.team_members:insert:why"', '"hd.team_members:rules:explain"', '"hd.team_members:update:items"', '"hd.team_members:update:refuse"', '"hd.team_members:update:why"', '"hd.teams:column id, workspace_id:items"', '"hd.teams:column id, workspace_id:why"', '"hd.teams:column parent_id after:items"', '"hd.teams:column parent_id after:why"', '"hd.teams:delete:items"', '"hd.teams:delete:why"', '"hd.teams:insert:items"', '"hd.teams:insert:refuse"', '"hd.teams:insert:why"', '"hd.teams:rules:explain"', '"hd.teams:update:items"', '"hd.teams:update:refuse"', '"hd.teams:update:why"', '"hd.tickets:column created_at:items"', '"hd.tickets:column created_at:why"', '"hd.tickets:column id, workspace_id, requester_id:items"', '"hd.tickets:column id, workspace_id, requester_id:why"', '"hd.tickets:column status after:items"', '"hd.tickets:column status after:why"', '"hd.tickets:column status:items"', '"hd.tickets:column status:why"', '"hd.tickets:column team_id, assignee_id:items"', '"hd.tickets:column team_id, assignee_id:why"', '"hd.tickets:delete:items"', '"hd.tickets:delete:why"', '"hd.tickets:insert:items"', '"hd.tickets:insert:refuse"', '"hd.tickets:insert:why"', '"hd.tickets:rules:explain"', '"hd.tickets:update:items"', '"hd.tickets:update:refuse"', '"hd.tickets:update:why"', '"hd.tickets:update_after:items"', '"hd.tickets:update_after:refuse"', '"hd.tickets:update_after:why"', '"hd.users:column customer_org_id:items"', '"hd.users:column customer_org_id:why"', '"hd.users:column email:items"', '"hd.users:column email:why"', '"hd.users:column id, workspace_id, kind:items"', '"hd.users:column id, workspace_id, kind:why"', '"hd.users:column name:items"', '"hd.users:column name:why"', '"hd.users:column notes:items"', '"hd.users:column notes:why"', '"hd.users:column role, active:items"', '"hd.users:column role, active:why"', '"hd.users:insert:items"', '"hd.users:insert:refuse"', '"hd.users:insert:why"', '"hd.users:rules:explain"', '"hd.users:update:items"', '"hd.users:update:refuse"', '"hd.users:update:why"', '"hd.workspaces:column id:items"', '"hd.workspaces:column id:why"', '"hd.workspaces:rules:explain"', '"hd.workspaces:update:items"', '"hd.workspaces:update:refuse"', '"hd.workspaces:update:why"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"hd_app"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.sign_out()', 'authz.connection_check()', 'authz.session_limited()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, uuid, text)', 'authz.explain(text, uuid, text, text)', 'authz.list_shares(text, uuid)', 'authz.list_links(text, uuid)', 'authz.revoke_link(text, uuid, text)', 'authz.create_link(text, uuid, text, timestamptz)', 'authz.create_role(text, uuid, text, text, text[])', 'authz.roles_of(text, uuid)', 'authz.request_access(text, uuid, text, text, interval)', 'authz.break_glass(text, uuid, text, text, interval)', 'authz.start_review(text, uuid, timestamptz)', 'authz.can(text, uuid, text)', 'authz.who_among(text, uuid, text, text[], text)', 'authz.perms(text, uuid)', 'authz.share(text, text, text, text, uuid, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, uuid, text)', 'authz.share(text, uuid, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, uuid, text, text, text, text)', 'authz.share(text, uuid, text, text, uuid, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, uuid, text, text, uuid, text)']::regprocedure[]))
UNION ALL
SELECT n.nspname::text, gw.who, a.privilege_type,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who)
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname = 'authz_sync' AND a.grantee <> n.nspowner
    AND NOT coalesce(a.grantee = to_regrole('"hd_electric"') AND a.privilege_type = 'USAGE', false)
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON TABLE %s FROM %s CASCADE', a.privilege_type, c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace = 'authz_sync'::regnamespace AND a.grantee <> c.relowner
    AND NOT coalesce(a.grantee = to_regrole('"hd_electric"') AND a.privilege_type = 'SELECT', false)
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace = 'authz_sync'::regnamespace AND att.attacl IS NOT NULL LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowstile''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

GRANT USAGE ON SCHEMA authz, authz_gen TO "hd_app";

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

-- Tables never analyzed (made just now, or too small for autovacuum to have reached them) are planned
-- as ten pages of rows: a table of 6 rows as thousands. Through the rules' lookups that becomes an estimate of
-- hundreds of thousands, and Postgres compiles (JIT) and plans for reads of a few rows. ANALYZE reads a
-- sample (30,000 rows at most) and blocks neither reads nor writes.
DO $an$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind = 'r' AND c.relpersistence <> 't' AND c.reltuples < 0
             AND pg_has_role(c.relowner, 'USAGE')
             AND (c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_int', 'authz_sync'))
                  OR c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"hd"."workspaces"', '"hd"."users"', '"hd"."support_access"', '"hd"."integrations"', '"hd"."customer_orgs"', '"hd"."teams"', '"hd"."team_members"', '"hd"."team_leads"', '"hd"."tickets"', '"hd"."comments"']::text[]) x)) LOOP
    EXECUTE format('ANALYZE %s', r.tbl);
  END LOOP;
END $an$;

-- the policy now in force
INSERT INTO authz.policy_versions (action, policy, files, version, lock)
VALUES ('apply', $authz_policy$-- The helpdesk: several companies' support desks (workspaces) on one database. Every rule about who may do what
-- is here; the app has no permission checks of its own. A workspace's people, tickets and roles are its own: the
-- boundary is written into the permissions below (`and workspace.agent`, `and workspace.member`), where
-- `rowstile prove` and the review read it, and the schema's composite keys hold it a second time. The vendor's
-- staff belong to no workspace: they reach one only when it lets them in, by break glass, for a while, on the
-- record.
app role hd_app

-- Electric serves the inbox and the ticket page live, from the sync index (README.md, "Live")
sync role hd_electric
sync hd.tickets : view
sync hd.comments : view

type workspace = hd.workspaces (id uuid)
  member : user = hd.users(workspace_id -> id)
  agent  : user = hd.users(workspace_id -> id) where {kind = 'agent'}
  admin  : user = hd.users(workspace_id -> id) where {kind = 'agent' and role = 'admin'}
  -- the vendor's staff the workspace lets in, while it does
  support   : user        = hd.support_access(workspace_id -> staff_id) where {until > now()}
  connected : integration = hd.integrations(workspace_id -> id)

  can manage       = admin
  can manage_roles = admin
  can work_all     = admin or (agent and {open_queue})
  can work         = agent
  can view         = member

-- a deactivated user is nobody: they hold nothing and sign in to nothing
type user = hd.users (id uuid) where {active}
  self      : user         = id
  workspace : workspace    = workspace_id
  org       : customer_org = customer_org_id

  -- an admin views the app as someone of their own workspace (authz.view_as: read-only, on the record)
  can impersonate = workspace.admin
  can see_notes   = workspace.work
  -- the requester's colleagues, where their customer org shares its tickets
  can org_tickets = org.see_tickets
  -- a workspace's agents are seen by its people: a customer sees who answered them (not the notes, see_notes)
  can view = self or workspace.work or (org.member and workspace.member) or (workspace.member and {kind = 'agent'})
          or workspace.connected

-- the email intake and the like: they sign in as themselves, with keys an admin makes
type integration = hd.integrations (id uuid) principal where {active}
  self      : integration = id
  workspace : workspace   = workspace_id

  can manage_keys = workspace.manage
  can view        = self or workspace.manage

type customer_org = hd.customer_orgs (id uuid)
  workspace : workspace = workspace_id
  member    : user      = hd.users(customer_org_id -> id)

  can see_tickets = member and {shared_tickets}
  can manage      = workspace.manage
  can view        = member or workspace.work

-- teams inside teams: a lead oversees the teams inside theirs
type team = hd.teams (id uuid)
  workspace : workspace = workspace_id
  parent    : team      = parent_id
  member    : user      = hd.team_members(team_id -> user_id)
  lead      : user      = hd.team_leads(team_id -> user_id)

  can oversee = lead or parent.oversee
  can manage  = workspace.manage or oversee
  can view    = workspace.work

type membership = hd.team_members (team_id uuid, user_id uuid)
  team   : team = team_id
  person : user = user_id

type leadership = hd.team_leads (team_id uuid, user_id uuid)
  team : team = team_id

type support_grant = hd.support_access (workspace_id uuid, staff_id uuid)
  workspace : workspace = workspace_id
  staff     : user      = staff_id

type ticket = hd.tickets (id uuid)
  workspace : workspace = workspace_id
  requester : user      = requester_id
  team      : team      = team_id
  assignee  : user      = assignee_id
  -- colleagues the requester or an agent copies in, of the ticket's own workspace
  cc : user shared by reply if {hd.same_workspace(this.object_id, this.subject_id)}
  -- the vendor's staff: by break glass where the workspace lets them in, or asked in by an admin
  responder : user shared by manage if {hd.is_staff(this.subject_id)}
  -- the workspace's own roles (Escalations, Billing specialist), made by its admins
  roles : user, team#member from workspace

  -- only the workspace's agents work its tickets, only its people take part, but for the vendor's staff. Every
  -- agent of the workspace sees its tickets: an agent who hands one to another team still sees it after, as
  -- Postgres asks of an update (the new row must be one its author may read)
  can work        = ((assignee or team.member or team.oversee or roles) and workspace.agent) or workspace.work_all or responder
  can reply       = work or ((requester or cc) and workspace.member)
  can view        = reply or workspace.agent or (requester.org_tickets and workspace.member) or workspace.connected
  can manage      = workspace.manage
  can share       = manage
  can break_glass = workspace.support

type comment = hd.comments (id uuid)
  ticket : ticket      = ticket_id
  author : user        = author_id
  via    : integration = integration_id

  -- an internal note is for those who work the ticket
  can view = ticket.work or (ticket.view and {not internal})

-- the email intake's keys: new tickets, new customers and replies, and nothing else
scope intake = hd.tickets.select, hd.tickets.insert, hd.users.select, hd.users.insert, hd.comments.select, hd.comments.insert, ticket.view, user.view, comment.view

rules hd.workspaces
  select    : view
  update    : manage
  update id : nobody

-- a person's name is theirs or an admin's to change; their email is how the email intake knows who sent a mail:
-- only an admin changes it
rules hd.users view hd.users_visible
  select                        : view
  insert                        : workspace.manage or ((workspace.work or workspace.connected) and {kind = 'customer'})
  update                        : self or workspace.manage or see_notes
  update notes                  : see_notes
  update role, active           : workspace.manage
  update customer_org_id        : workspace.work
  update name                   : self or workspace.manage
  update email                  : workspace.manage
  update id, workspace_id, kind : nobody
  mask notes                    : see_notes

rules hd.integrations
  select                  : view
  insert                  : workspace.manage
  update                  : workspace.manage
  update id, workspace_id : nobody
  delete                  : workspace.manage

rules hd.customer_orgs
  select                  : view
  insert                  : workspace.manage
  update                  : manage
  update id, workspace_id : nobody
  delete                  : manage

rules hd.teams
  select                  : view
  insert                  : workspace.manage
  update                  : manage
  update parent_id after  : parent.manage
  update id, workspace_id : nobody
  delete                  : workspace.manage

rules hd.team_members
  cascade from hd.teams
  cascade from hd.users
  select : team.view
  insert : team.manage
  update : nobody
  delete : team.manage or person.self

rules hd.team_leads
  cascade from hd.teams
  cascade from hd.users
  select : team.view
  insert : team.manage
  update : nobody
  delete : team.manage

rules hd.support_access
  cascade from hd.workspaces
  cascade from hd.users
  select : workspace.manage or staff.self
  insert : workspace.manage and {until <= now() + interval '7 days' and hd.is_staff(staff_id::text)}
  update : nobody
  delete : workspace.manage

-- no one dates a ticket again (the inbox's order)
rules hd.tickets
  select : view
  insert : (workspace.view and requester and {status = 'open' and team_id is null and assignee_id is null}) or workspace.work or workspace.connected
  update : work or requester
  -- whoever works a ticket may hand it to another agent of the workspace, and no longer work it after
  update after                          : workspace.work or requester
  update status                         : work or (requester and {status <> 'closed'})
  update status after                   : work or {status in ('open', 'solved')}
  update team_id, assignee_id           : work
  update id, workspace_id, requester_id : nobody
  update created_at                     : nobody
  delete                                : workspace.manage

rules hd.comments
  cascade from hd.tickets
  select : view
  insert : (ticket.work and author) or (ticket.reply and author and {not internal}) or (ticket.view and via and {not internal})
  update : nobody
  delete : nobody

invariants
  never ticket: view and not workspace.member and not responder and not workspace.connected
  never ticket: work and not workspace.agent and not responder
  never comment: view and not ticket.view
  never user: view and not self and not workspace.member and not workspace.connected
$authz_policy$,
  $authz_files${}$authz_files$::jsonb, '0.1.0-dev+120a9ef5d480', '3a92ad4e2011d9a1');

-- the session made read-only above (its statements committed one by one) is as it was again
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_migration.read_only', true) <> '' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', pg_catalog.current_setting('authz_migration.read_only'), false);
    PERFORM pg_catalog.set_config('authz_migration.read_only', '', false);
  END IF;
END $authz_tx$;
